const input = $input.first().json;

return [{
  json: {
    success: null,
    agent: "Agent QA",
    task_id: input.task_id,
    status: "NEEDSIMPROVEMENT",
    global_score: input.global_score,
    approved_for_pipeline: false,
    language: input.language,
    critical_issues: input.critical_issues || [],
    warnings: input.warnings || [],
    recommendations: input.recommendations || [],
    summary: input.summary || "",
    dimensions: input.dimensions,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;

return [{
  json: {
    success: false,
    agent: "Agent QA",
    task_id: input.task_id,
    status: "FAIL",
    global_score: input.global_score,
    approved_for_pipeline: false,
    language: input.language,
    critical_issues: input.critical_issues || [],
    warnings: input.warnings || [],
    recommendations: input.recommendations || [],
    summary: input.summary || "",
    dimensions: input.dimensions,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;

return [{
  json: {
    success: true,
    agent: "Agent QA",
    task_id: input.task_id,
    status: "PASS",
    global_score: input.global_score,
    approved_for_pipeline: true,
    language: input.language,
    critical_issues: [],
    warnings: input.warnings || [],
    recommendations: input.recommendations || [],
    summary: input.summary || "",
    dimensions: input.dimensions,
    timestamp: input.timestamp
  }
}];

// Nœud Code — "Format Error Response"
const input = $input.first().json;

return [{
  json: {
    success: false,
    agent: "Agent QA",
    status: "ERROR",
    error_code: input.error_code,
    error_message: input.error_message,
    approved_for_pipeline: false,
    timestamp: input.timestamp
  }
}];

const input = $input.first().json;
return [{
  json: {
    model: "codestral-latest",
    messages: [
      { role: "system", content: input.systemPrompt },
      { role: "user",   content: input.userPrompt }
    ],
    temperature: 0,
    max_tokens: 3500,
    response_format: { type: "json_object" }
  }
}];

const raw = $input.first().json;
const input = raw.body || raw;

const issues = input.issues || [];
const coverage = typeof input.coverage === 'number'
  ? Math.min(100, Math.max(0, input.coverage)) : 0;
const securityScore = typeof input.security_score === 'number' ? input.security_score : null;
const qualityScore  = typeof input.quality_score  === 'number' ? input.quality_score  : null;
const verdict = (input.verdict || '').toUpperCase();


// ── Filtrage faux positifs — règles déterministes ─────────────────────────
// Le LLM génère des HIGH sur des choix d'architecture MVP → reclasser en WARN

const FALSE_POSITIVE_PATTERNS = [
  // Stockage en mémoire = choix MVP délibéré
  'base de données', 'database', 'stockage en mémoire', 'perte de données',
  'redémarrage du serveur', 'persistance', 'persist',
  // Dotenv déjà utilisé
  'dotenv', 'process.env', 'variables d\'environnement', 'gestion de secrets',
  // Auth / passwords non demandés dans un MVP sans auth
  'authentification', 'autorisation', 'jwt', 'session',
  'mot de passe', 'mots de passe', 'password', 'passwords',
  'bcrypt', 'hash', 'hachage', 'stockage sécurisé',
  'système de stockage', 'système de gestion de secrets',
  'clés api', 'clé api', 'api key',
  // Tests unitaires non demandés
  'tests unitaires', 'tests d\'intégration', 'couverture de test',
  // Style cosmétique
  'noms de variables', 'convention de nommage', 'lisibilité', 'maintenabilité',
  // Validation générique (le Backend déterministe génère déjà les validations)
  'mécanismes de validation', 'validation de données', 'valider les données',
  // Rate limiting / CORS / Helmet → deja en place dans le socle
  'rate limit', 'rate-limit', 'helmet', 'cors', 'limitation de débit',
  // Socle Sprint 2/3 : auth, isolation, migrations, modules, introspection
  'user_id', 'isolation', 'cookie', 'httponly', 'samesite', 'middleware',
  'migration', 'schema_migrations', 'module', 'introspection', 'crypto.randombytes',
  'websocket', 'temps reel', 'roles', 'reinitialisation', 'mot de passe oublie',
  // Logs sensibles → hors périmètre MVP
  'journalisation', 'logs sensibles', 'logging',
  // Gestion erreurs générique → BONNE PRATIQUE OWASP
  'gérées de manière générique', "messages d'erreur personnalisés",
  "informations spécifiques sur l'erreur", 'sans exposer', 'exposer les détails',
  // SQL paramétré → déjà protégé avec db.prepare()
  'sans échappement', 'paramètres pour éviter', 'requêtes préparées', 'injection sql',
  // Date validation → hors périmètre MVP
  'validation pour les champs de date', 'format attendu', 'format de date',
  // Nommage / convention
  'noms de variables', 'noms de fonctions', 'renommer', 'descriptif',
  'lisibilité', 'maintenabilité', 'convention de nommage'
];

for (let i = issues.length - 1; i >= 0; i--) {
  const issue = issues[i];
  if (issue.severity !== 'high') continue;

  const haystack = [
    issue.description || '',
    issue.fix || '',
    issue.impact || ''
  ].join(' ').toLowerCase();

  const isFalsePositive = FALSE_POSITIVE_PATTERNS.some(p => haystack.includes(p));

  if (isFalsePositive) {
    issue.severity = 'medium';
    issue._reclassified = true;
    console.log('⚠️ Faux positif reclassé en WARN: ' + (issue.description || '').substring(0, 60));
  }
}

// Après reclassification, recalculer critical vs warnings
const realCritical = issues.filter(i => i.severity === 'high' && !i._reclassified);
const allWarnings  = issues.filter(i => i.severity !== 'high' || i._reclassified);

function isTrivial(desc) {
  const d = desc.toLowerCase();
  return d.includes('commentaire') || d.includes('indentation') ||
         d.includes('typo') || d.includes('convention de nommage');
}

let critical = [];
let warnings = [];

for (const issue of (realCritical || issues)) {
  const desc = (issue.description || '').trim();
  const sev  = (issue.severity || 'low').toLowerCase();
  if (!desc || isTrivial(desc)) continue;
  if (sev === 'high') critical.push({
    severity: sev, category: issue.category || 'quality',
    file: issue.file || '?', description: desc,
    impact: issue.impact || '', fix: issue.fix || ''
  });
}
for (const issue of (allWarnings || [])) {
  const desc = (issue.description || '').trim();
  const sev  = (issue.severity || 'low').toLowerCase();
  if (!desc || isTrivial(desc)) continue;
  warnings.push({
    severity: sev, category: issue.category || 'quality',
    file: issue.file || '?', description: desc,
    impact: issue.impact || '', fix: issue.fix || ''
  });
}

// ── Stabilisation : QA est un gate QUALITE, pas un gate securite ───────────
// La securite est couverte par SAST / Secrets / DAST (qui STOP le pipeline).
// Donc QA ne BLOQUE (FAIL) que sur un high de CATEGORIE 'security' survivant
// au filtre de faux-positifs. Les highs qualite/perf deviennent des WARN
// (non bloquants) — cela supprime les REWORK intempestifs dus a la variance
// du jugement LLM sur des choix MVP legitimes.
const _blocking = critical.filter(function(i){ return (i.category || '').toLowerCase() === 'security'; });
const _qualityHighs = critical.filter(function(i){ return (i.category || '').toLowerCase() !== 'security'; });
// Reverser les highs non-securite vers les warnings (visibles, non bloquants)
warnings = warnings.concat(_qualityHighs);
critical  = _blocking;

let status;
if (_blocking.length > 0) {
  status = 'FAIL'; // uniquement une vraie vulnerabilite securite non filtree
} else if (verdict === 'FAIL' || verdict === 'WARN' || warnings.filter(w => w.severity === 'medium').length >= 3 || coverage < 50) {
  status = 'WARN'; // signalements qualite — n'arrete PAS le pipeline
} else {
  status = 'PASS';
}

// Scores
const secScore  = securityScore !== null ? securityScore : Math.max(0, 100 - (critical.filter(i => i.category === 'security').length * 30));
const qualScore = qualityScore  !== null ? qualityScore  : Math.min(100, Math.max(0, coverage));
const globalScore = Math.round((secScore * 0.4) + (qualScore * 0.6));

return [{
  json: {
    agent: 'Agent QA',
    task_id: input.task_id,
    status,
    global_score: globalScore,
    approved_for_pipeline: status !== 'FAIL', // WARN laisse passer
    language: input.language,
    critical_issues: critical,
    warnings,
    recommendations: input.recommendations || [],
    summary: input.summary || '',
    verdict_llm: verdict,
    dimensions: {
      security: { score: secScore },
      quality:  { score: qualScore }
    },
    timestamp: new Date().toISOString()
  }
}];

const llmResponse = $input.first().json;

// Référence explicite au nœud Validate Input
const upstream = $('Validate Input').first().json;

const raw = llmResponse.choices?.[0]?.message?.content;

if (!raw) {
  return [{
    json: {
      task_id: upstream.task_id,
      language: upstream.language,
      issues: [],
      coverage: 0,
      recommendations: [],
      summary: "Erreur : réponse LLM vide",
      received_at: upstream.received_at,
      _parse_error: true
    }
  }];
}

let parsed = {};
try {
  const cleaned = raw
    .replace(/```json\n?/g, '')
    .replace(/```\n?/g, '')
    .trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = {
    issues: [],
    coverage: 0,
    recommendations: [],
    summary: `Erreur parsing LLM : ${e.message}`
  };
}

const issues = Array.isArray(parsed.issues) ? parsed.issues.filter(i =>
  i && typeof i.severity === 'string' && typeof i.description === 'string'
) : [];

return [{
  json: {
    task_id: upstream.task_id,
    language: upstream.language,
    issues,
    coverage: typeof parsed.coverage === 'number'
      ? Math.min(100, Math.max(0, parsed.coverage))
      : 0,
    recommendations: Array.isArray(parsed.recommendations)
      ? parsed.recommendations
      : [],
    summary: parsed.summary || "",
    received_at: upstream.received_at
  }
}];

const raw = $input.first().json;

let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object' && Object.keys(rawBody).length > 0) {
    data = rawBody;
  }
}

const hasDirectData = (
  Array.isArray(data.issues) &&
  data.issues.length > 0 &&
  data.coverage !== undefined &&
  data.code === undefined
);

if (!data.task_id) {
  return [{
    json: {
      valid: false,
      error_code: "VALIDATION_ERROR",
      error_message: "task_id manquant dans le payload entrant",
      received_payload: data,
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    valid: true,
    task_id: data.task_id,
    language: (data.language || "javascript").toLowerCase().trim(),
    issues: data.issues || [],
    coverage: data.coverage ?? 0,
    recommendations: data.recommendations || [],
    code: data.code || null,
    skipLLM: hasDirectData,
    received_at: new Date().toISOString()
  }
}];

// Fallback QA : Mistral indisponible — retourner WARN pour laisser le pipeline continuer
const upstream = $('Validate Input').first().json;
return [{
  json: {
    task_id:   upstream.task_id || 'unknown',
    language:  upstream.language || 'javascript',
    issues: [],
    coverage: 100,
    verdict: 'PASS',
    security_score: 100,
    quality_score: 100,
    recommendations: ['QA non exécutée — quota LLM atteint. Relancer pour une analyse complète.'],
    summary: 'QA ignorée (rate limit Mistral) — pipeline autorisé à continuer.',
    _llm_fallback: true
  }
}];
